"""Hindi text for the Rule page. TEXT = {key: translated inner HTML}."""
TEXT = {
"k34706326": "प्रार्थना-नियम के विषय में",
"kc1ba8633": "कितनी प्रार्थना करनी चाहिए, और अपनी सामर्थ्य के अनुसार प्रार्थना करने के विषय में कलीसिया के स्रोत क्या कहते हैं। यह पृष्ठ उन स्रोतों को प्रस्तुत करता है; उनमें परामर्श नहीं जोड़ता।",
"ka7965ff8": "<strong>पहले यह पढ़िए।</strong> Plithos में जो कुछ है वह संदर्भ के लिए है, आपको नापने का माप नहीं। प्रार्थनाएँ, उपवास का नियम, प्रहर और आराधना की विधियाँ यहाँ पूरी दी गई हैं, क्योंकि वे कलीसिया की विरासत हैं और सबकी पहुँच में होनी चाहिए। उन्हें पूरा देना यह कहना नहीं है कि किसी को वह सब निभाना ही है।",
"kef5c7431": "जो नियम आप निभाते हैं वह आपका आध्यात्मिक पिता आपकी जानकारी, आपकी सामर्थ्य और आपकी परिस्थितियों के अनुसार निश्चित करता है। इस स्थल की कोई बात उससे ऊपर नहीं, और यहाँ कुछ भी उस पर निर्णय नहीं जो छपे हुए से कम प्रार्थना करता है। जो प्रभु की प्रार्थना दिन में तीन बार मन से कहता है, वह उसी नियम को निभा रहा है जो कलीसिया ने पहली शताब्दी में दिया।",
"kfd250c56": "यह पृष्ठ वही प्रस्तुत करता है जो स्रोत कहते हैं, और अपना परामर्श नहीं जोड़ता। जहाँ किसी वाक्य के साथ संदर्भ नहीं, वहाँ वह इस स्थल के विषय में कथन है, आपकी प्रार्थना के विषय में निर्देश नहीं। मार्गदर्शन आपके पुरोहित का है, जो आपका जीवन जानता है; यह स्थल उसे नहीं जानता।",
"kd06d4f8a": "सबसे प्राचीन नियम वास्तव में क्या था",
"kc90dad01": "बची हुई सबसे प्राचीन ईसाई आचार-पुस्तिका दिदाखे है, लगभग सन् 100 की। उसका प्रार्थना-नियम है दिन में तीन बार प्रभु की प्रार्थना।",
"kadda83fe": "दिन में तीन बार इस प्रकार प्रार्थना करो।",
"k513c7122": "दिदाखे 8 &middot; अनु. M. B. Riddle, 1886 &middot; <a href=\"/library#work=didache\">पुस्तकालय में पढ़ें</a>",
"k355facce": "वही ग्रंथ, दो अध्याय पहले, माप के सिद्धांत को सीधे कहता है, और यह आधुनिक ढील नहीं बल्कि इस विषय पर कलीसिया का लिखा सबसे प्राचीन वचन है:",
"k0133b448": "क्योंकि यदि तू प्रभु का सारा जुआ उठा सके, तो तू सिद्ध होगा; परंतु यदि नहीं उठा सके, तो जो कर सके वही कर।",
"kec4ccf0b": "दिदाखे 6 &middot; अनु. M. B. Riddle, 1886 &middot; <a href=\"/library#work=didache\">पुस्तकालय में पढ़ें</a>",
"ka800cdac": "बाद की प्रार्थना-पुस्तकों की अधिक पूर्ण प्रार्थना-विधियाँ इसके बाद विकसित हुईं। दिदाखे बस वही सबसे प्राचीन लिखित नियम है जो कलीसिया के पास है, और यही उसकी माँग है।",
"kc8529ac1": "संख्या ही माप नहीं है",
"k605c07f5": "संत यूहन्ना कस्सियन, पाँचवीं शताब्दी के आरंभ में मिस्र के पिताओं की शिक्षा लिखते हुए, प्रार्थना को उन घड़ियों से गिनने के विरुद्ध चेताते हैं जिन्हें कोई उसके लिए विशेष रूप से अलग रखता है:",
"kda219ca8": "क्योंकि वह बहुत ही थोड़ी प्रार्थना करता है जिसे केवल उन्हीं घड़ियों में प्रार्थना करने की आदत है जब वह घुटने टेकता है।",
"k87ef1fff": "संत यूहन्ना कस्सियन, वार्ताएँ 10.14 &middot; अनु. Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">पुस्तकालय में पढ़ें</a>",
"k6f06dcb5": "अतः कस्सियन के यहाँ प्रार्थना का माप नियत घड़ियों से अधिक व्यापक है, और यह वचन उन्हीं की ओर है जो उसे उन घड़ियों में बाँध देते हैं। यह विचार उन्होंने आरंभ नहीं किया। प्रेरित पहले ही नियम को ऐसे रूप में दे चुके थे जिसे कोई घड़ी नहीं समा सकती:",
"k9d16dd79": "हर समय और हर प्रकार से आत्मा में प्रार्थना, और विनती करते रहो, और इसी लिये जागते रहो कि सब पवित्र लोगों के लिये लगातार विनती किया करो,",
"kd45e4afe": "इफिसियों 6:18",
"k8ff6957a": "और इससे भी संक्षेप में: <em>निरंतर प्रार्थना करते रहो</em> (1 थिस्सलुनीकियों 5:17)। नियत घड़ियों का नियम उसी की सेवा करता है; उसे समाप्त नहीं करता।",
"k94022491": "यह क्रम है, सीढ़ी नहीं",
"k6f5ac9c2": "आगे जो है वह Plithos द्वारा निर्धारित श्रेणियाँ नहीं हैं। यह उसका क्रम है जो स्रोतों और प्राप्त पुस्तकों में है, इस आधार पर कि प्रत्येक दिन में से कितना माँगता है। <strong>इनमें से कौन किस व्यक्ति पर लागू होता है, यह उसके आध्यात्मिक पिता का प्रश्न है, इस पृष्ठ का नहीं।</strong>",
"kbd0070ec": "यह सीढ़ी नहीं है, और पहली प्रविष्टि ही इसका कारण है। यीशु-प्रार्थना पहले इसलिए है कि वह मनुष्य की परिस्थितियों से सबसे कम माँगती है, इसलिए नहीं कि मनुष्य से सबसे कम माँगती है। वही प्रार्थना है जिसे मौन के पिता समूची प्रार्थना कहते हैं, और जो बहुत आगे बढ़े हुओं को हर लिखी हुई वस्तु के बदले दी जाती है। वह एक साथ दोनों छोरों पर खड़ी है।",
"kec53651e": "यीशु-प्रार्थना",
"kd76e85df": "जब न समय हो, न पुस्तक, न शांति - यात्रा में, काम पर, रोग में, जब न खड़े हो सकें और न बोल सकें",
"k15c8fcc6": "यीशु-प्रार्थना अपने पूर्ण रूप में: <em>प्रभु यीशु मसीह, परमेश्वर के पुत्र, मुझ पापी पर दया कर।</em> जहाँ यह भी अधिक हो, वहाँ पिता संक्षिप्त रूपों की अनुमति देते हैं - <em>प्रभु यीशु मसीह, मुझ पर दया कर</em>, या केवल <em>प्रभु, दया कर</em>। इसे न पुस्तक चाहिए, न खड़ा होना, न स्वर, और इसे साधारण कार्य-दिवस भर साथ रखा जा सकता है।",
"k433c6e1a": "<a href=\"/prayers#s=heart\">यीशु-प्रार्थना, और उसे निभाने पर पिताओं का परामर्श</a>",
"k0607d349": "वह पहले इसलिए है कि हर परिस्थिति में बनी रहती है, इसलिए नहीं कि यहाँ दिए गए में सबसे छोटी है। कस्सियन, वार्ताएँ 10.14: \"वह बहुत ही थोड़ी प्रार्थना करता है जिसे केवल उन्हीं घड़ियों में प्रार्थना करने की आदत है जब वह घुटने टेकता है।\"",
"k4fbd7571": "प्रभु की प्रार्थना, दिन में तीन बार",
"kccf34183": "जब संभव हो, नियत घड़ियों में नियत नियम",
"k6c98a369": "हमारे पास जो सबसे प्राचीन ईसाई पुस्तिका है उसका नियम। यह छोटा नियम है, पर नियत घड़ियों का नियम है, और इसलिए टूटे हुए दिन से यीशु-प्रार्थना की अपेक्षा अधिक माँगता है।",
"kb80095bf": "दिदाखे 8।",
"k73f947ac": "सारोव के संत सेराफिम का नियम",
"kbeb11458": "उनके लिए जिनका काम लंबे नियम की जगह नहीं छोड़ता",
"kba90cd4c": "उठने पर, प्रतिमाओं के सामने खड़े होकर: प्रभु की प्रार्थना तीन बार, <em>हे कुँवारी परमेश्वर-जननी, आनंद कर</em> तीन बार, और विश्वास-सूत्र एक बार। फिर काम पर, सारी सुबह चुपचाप यीशु-प्रार्थना कहते हुए, और दोपहर बाद <em>हे परम पवित्र परमेश्वर-जननी, मुझे बचा</em>। सोने से पहले वही छोटा नियम फिर से।",
"k6464f90a": "संत सेराफिम ने इसे उन श्रमिकों और गृहस्थों को दिया जो प्रार्थना-पुस्तक की अधिक पूर्ण प्रातः और संध्या की प्रार्थनाएँ नहीं निभा सकते थे, और उन्होंने इसे ऐसी छूट नहीं माना जिससे आगे बढ़ जाना हो। यह नियत घड़ियों की नियत प्रार्थनाओं का नियम है, जो कार्य-दिवस भर चलने वाली प्रार्थना से जुड़ा है, और इसीलिए यह यहाँ है, नीचे नहीं।",
"kc823332f": "सारोव के संत सेराफिम, गृहस्थों को दी उनकी शिक्षाओं में। प्रार्थनाएँ स्वयं प्रार्थना-पृष्ठ पर हैं।",
"k3041ac63": "प्रातः और संध्या",
"k225e3ccd": "गृहस्थ के लिए प्रार्थना-पुस्तक का प्रचलित नियम",
"kf4d2a2e5": "उठने पर प्रातः की प्रार्थनाएँ और सोने से पहले संध्या की, ध्यान से कही गईं, जल्दबाज़ी में नहीं।",
"k98ad4446": "<a href=\"/prayers#s=daily\">प्रातः और संध्या की प्रार्थनाएँ</a>",
"k8ad36869": "एकांतवासी संत थेओफान प्रार्थना-पुस्तक की प्रातः और संध्या की प्रार्थनाओं को आरंभ करने वाले गृहस्थ के लिए पूर्णतः पर्याप्त मानते थे। अधिक विस्तृत परामर्श के लिए प्रार्थना-पृष्ठ की टिप्पणी देखें।",
"k4cecadd4": "प्रहरों के साथ",
"kefb7d0a1": "जहाँ दिन इसकी अनुमति दे",
"k8fb45542": "दिन भर की छोटी विधियाँ, पहले प्रहर से रात्रि-प्रार्थना तक।",
"k6b300612": "<a href=\"/prayers#s=hours\">प्रहर</a>",
"k61610f0a": "दिदाखे की तीन दैनिक प्रार्थनाएँ इस चक्र का बीज हैं। पूरे प्रहर होरोलोगियोन में दिए गए हैं।",
"kb3c5ab3d": "प्रभुभोज के लिए तैयारी",
"k8dbdf873": "रहस्यों को ग्रहण करने से पहले",
"kced3fbfd": "तैयारी की विधि, चालीस के सामने कही जाने वाली दो प्रार्थनाएँ, और उसके बाद का धन्यवाद। विधि का कितना भाग कहा जाता है, और वह पिछली संध्या को निभाई जाती है या उसी प्रातः, यह परंपरा से भिन्न है और आध्यात्मिक पिता निश्चित करता है। पिता निकट आने की वास्तविक शर्त किसे मानते हैं, नीचे देखें।",
"k8f37e928": "<a href=\"/prayers#s=communion\">पवित्र प्रभुभोज की प्रार्थनाएँ, उनके तीन भागों में</a>",
"k88dda4ec": "स्लाव और यूनानी परंपराओं के बीच व्यवहार में स्पष्ट अंतर है, अपेक्षित तैयारी में भी और विश्वासी कितनी बार ग्रहण करते हैं इसमें भी।",
"ka6cba0b8": "जब आप अपना नियम न निभा सकें",
"k87db3602": "यात्रा, रोग, रात की नौकरी, छोटे बच्चे, शोक और थकान - ये सब नियम को तोड़ते हैं। ऊपर दिए गए पाठों में से दो सीधे इसी से संबंधित हैं।",
"k8dcf4ab6": "<strong>दिदाखे नियम को सब कुछ या कुछ नहीं के रूप में नहीं रखता।</strong> उसका निर्देश यह नहीं कि पूरा जुआ उठाओ या कुछ भी नहीं, बल्कि यह कि जहाँ पूरा नहीं उठाया जा सकता, वहाँ \"जो कर सके वही कर\"।",
"ka4ac033d": "<strong>प्रार्थना खड़े होने की घड़ियों में बंद नहीं है।</strong> ऊपर दिए कस्सियन के वचन की शक्ति यही है: वह उन्हें डाँटते हैं जो अपनी प्रार्थना केवल घुटने टेकने की घड़ियों से गिनते हैं, और यह उन घड़ियों के बाहर की प्रार्थना को गिनती के भीतर लाता है, बाहर नहीं करता। यीशु-प्रार्थना अपने प्राप्त संक्षिप्त रूपों में न पुस्तक माँगती है, न देह की मुद्रा, न स्वर।",
"k1c9eeaa9": "पिता निकट आने की शर्त किसे मानते हैं",
"keac4f2df": "तैयारी की विधि सच्चा भला है और सच्ची विरासत है। पर वह वह नहीं है जो मनुष्य को ग्रहण करने योग्य बनाती है। इस विषय में पिता स्पष्ट हैं, और वे तब लिख रहे थे जब कोई छपी हुई तैयारी-विधि थी ही नहीं।",
"kc356b366": "संत यूहन्ना क्रिसोस्तोम इब्रानियों पर उपदेश देते हुए ठीक यही प्रश्न उठाते हैं कि कितनी बार और कितना, और इन्हीं शब्दों में उत्तर देने से इनकार करते हैं:",
"kce69ff57": "तो फिर क्या? हम किसे सराहें? उन्हें जो वर्ष में एक बार ग्रहण करते हैं? उन्हें जो बहुत बार ग्रहण करते हैं? उन्हें जो कभी-कभार ग्रहण करते हैं? न उन्हें जो एक बार, न उन्हें जो बार-बार, न उन्हें जो कभी-कभार, बल्कि उन्हें जो शुद्ध विवेक से, शुद्ध हृदय से, निर्दोष जीवन से निकट आते हैं। ऐसे लोग निरंतर निकट आएँ; परंतु जो ऐसे नहीं, वे एक बार भी नहीं।",
"k2d880e69": "संत यूहन्ना क्रिसोस्तोम, इब्रानियों पर उपदेश 17 &middot; अनु. Frederic Gardiner &middot; <a href=\"/library#work=chrysostom-homilies-hebrews\">पुस्तकालय में पढ़ें</a>",
"k3448180a": "क्रिसोस्तोम जिस कसौटी का नाम लेते हैं वह विवेक की दशा है। वे कोई संख्या नहीं बताते, न प्रभुभोज की और न पहले कही गई प्रार्थनाओं की, और आवृत्ति के प्रश्न को गलत प्रश्न मानकर एक ओर रख देते हैं।",
"k4bc3e896": "संत यूहन्ना कस्सियन दूसरे आधे भाग को लेते हैं, और अध्याय का शीर्षक स्पष्ट कहता है: <em>कि यद्यपि हम मानते हैं कि हम पाप रहित नहीं हो सकते, फिर भी हमें प्रभु के प्रभुभोज से दूर नहीं रहना चाहिए।</em>",
"k3620ced2": "फिर भी हमें प्रभु के प्रभुभोज से इसलिए दूर नहीं रहना चाहिए कि हम स्वयं को पापी मानते हैं, बल्कि अपनी आत्मा की चंगाई और अपनी अंतरात्मा की शुद्धि के लिए और भी अधिक उत्सुकता से उसकी ओर दौड़ना चाहिए, और मन की दीनता और विश्वास के साथ अपने घावों की औषधि ही ढूँढ़नी चाहिए, स्वयं को इतने बड़े अनुग्रह के योग्य न मानते हुए।",
"k99dd8e07": "अन्यथा हम वर्ष में एक बार भी योग्य रीति से प्रभुभोज नहीं ले सकते, जैसा कुछ लोग करते हैं जो मठों में रहते हैं और स्वर्गीय रहस्यों की गरिमा, पवित्रता और मूल्य को ऐसा मानते हैं कि सोचते हैं कि संतों और निष्कलंक जनों के सिवा कोई उन्हें लेने का साहस न करे, न कि यह कि वे लेने से ही हमें संत और शुद्ध बनाएँगे। और इसी से वे उससे भी बड़े अभिमान और घमंड में गिरते हैं जिससे बचते हुए वे स्वयं को समझते हैं, क्योंकि जिस समय वे लेते हैं, उस समय वे स्वयं को लेने के योग्य मानते हैं।",
"kb8b440b1": "संत यूहन्ना कस्सियन, वार्ताएँ 23.21 &middot; अनु. Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">पुस्तकालय में पढ़ें</a>",
"kcab416e7": "कस्सियन का तर्क यह है कि अयोग्यता की भावना से दूर रहना ही बड़ा अभिमान है, क्योंकि जो योग्य होने तक दूर रहता है वह मान लेता है कि किसी और दिन वह योग्य होता। इसके विरुद्ध वे यह रखते हैं कि उनके कहने के अनुसार रहस्य किसलिए हैं: पहले से शुद्ध लोगों के लिए पुरस्कार नहीं, बल्कि वह साधन जिससे, उन्हीं के शब्दों में, वे लेने से हमें संत और शुद्ध बनाएँगे।",
"k1ceaa3c4": "कलीसिया प्रभुभोज लेने वाले से अपने विषय में क्या कहलवाती है",
"k15496498": "यह माप को नीचा करना नहीं है। यही माप है, और कलीसिया इसे हर निकट आने वाले के मुँह में रखती है। चालीस के सामने ऊँचे स्वर में समस्त मंडली द्वारा कही जाने वाली स्वीकारोक्ति यह नहीं कहती कि कहने वाला पहुँच चुका है:",
"kffb87ae9": "हे प्रभु, मैं विश्वास करता हूँ और स्वीकार करता हूँ कि तू सचमुच मसीह है, जीवित परमेश्वर का पुत्र, जो पापियों का उद्धार करने जगत में आया, जिनमें सबसे पहला मैं हूँ।",
"kd40a122c": "ग्रहण करने से पहले की प्रार्थना &middot; 1 तीमुथियुस 1:15 के अनुसार &middot; <a href=\"/prayers#s=communion\">प्रार्थना-पुस्तक में पढ़ें</a>",
"k91d95d94": "प्रेरित के अपने शब्द हैं <em>मसीह यीशु पापियों का उद्धार करने के लिये जगत में आया, जिनमें सबसे बड़ा मैं हूँ</em>, और कलीसिया ने उन्हें पत्री में नहीं छोड़ा। उसने उन्हें चालीस के सामने रखा और हर ग्रहण करने वाले को दिया कि वह उन्हें प्रथम पुरुष में कहे, उसी दिन जब वह ग्रहण करता है। संत वे हैं जिन्होंने यह वाक्य कहा और मन से कहा, वे नहीं जो ऐसे स्थान पर पहुँच गए जहाँ यह उन पर लागू होना बंद हो गया। अनुग्रह दिया जाता है; हमसे यही माँगा जाता है कि हम उत्तर दें, दी गई आज्ञाओं को मानें, और उन्हें न मान पाने के बाद भी उत्तर देते रहें।",
"kf78cb40a": "व्यवहार में इसका अर्थ क्या है",
"k87e5b047": "<strong>यह विधि कैनन-संबंधी शर्तों में नहीं है।</strong> कलीसिया का कोई कैनन ग्रहण करने से पहले इसकी माँग नहीं करता, और छपा हुआ नियत क्रम कैननों से बाद का है; उसमें से कितना कहा जाए यह आध्यात्मिक पिता निश्चित करता है।",
"k0e542bbd": "<strong>परंपरा वास्तव में जिनका नाम लेती है</strong> वे चालीस से पहले हैं: ऐसा विवेक जो बिना पश्चात्ताप वाले पाप में न टिका हो, पड़ोसी से मेल, प्रभुभोज का उपवास, और स्वीकारोक्ति के विषय में आध्यात्मिक पिता की आज्ञाकारिता। कस्सियन ऊपर के अंश में सीधे उसका प्रकरण लेते हैं जो अयोग्यता के भाव से दूर हो गया; क्रिसोस्तोम उसका जो संख्याओं से गिनता है।",
"k21c606eb": "<strong>प्रभुभोज का उपवास कैनन के अनुसार है, रीति मात्र नहीं।</strong> अफ्रीकी संहिता ने इसकी माँग की, वर्ष में केवल एक अपवाद की अनुमति देते हुए, उस दिन जब प्रभु के भोज का स्मरण किया जाता है:",
"k253a3d17": "कि वेदी के संस्कार उपवास करने वालों के सिवा किसी और द्वारा न किए जाएँ, केवल प्रभु के भोज के स्मरण की वर्ष में एक वर्षगाँठ को छोड़कर; क्योंकि यदि किन्हीं दिवंगत जनों का, चाहे धर्माध्यक्ष हों या अन्य, स्मरण दोपहर बाद करना हो, तो वह केवल प्रार्थनाओं से हो, यदि सेवा करने वाले भोजन कर चुके हों।",
"kb289f398": "अफ्रीकी संहिता (419), कैनन 41 &middot; अनु. Henry R. Percival, 1900 &middot; <a href=\"/library#work=canons-ecumenical\">पुस्तकालय में पढ़ें</a>",
"kfd9e4371": "त्रुल्लो की महासभा ने वह कैनन लिया और अपवाद हटा दिया:",
"k97125890": "कार्थेज की सभा का एक कैनन कहता है कि वेदी के पवित्र रहस्य उपवास करने वालों के सिवा किसी और द्वारा न किए जाएँ, केवल वर्ष में एक दिन को छोड़कर जिसमें प्रभु का भोज मनाया जाता है। उस समय, संभवतः उन स्थानों में कलीसिया के लिए उपयोगी कुछ परिस्थितियों के कारण, स्वयं पवित्र पिताओं ने भी यह छूट ली। परंतु चूँकि कोई बात हमें ठीक-ठीक पालन छोड़ने को प्रेरित नहीं करती, हम ठहराते हैं कि प्रेरितिक और पितृ-परंपरा का अनुसरण किया जाए; और हम निश्चित करते हैं कि महाउपवास के अंतिम सप्ताह के पाँचवें दिन उपवास तोड़ना और इस प्रकार समूचे महाउपवास का अनादर करना उचित नहीं।",
"k5c17110d": "त्रुल्लो, अर्थात् पंचम-षष्ठ महासभा (692), कैनन 29 &middot; अनु. Henry R. Percival, 1900 &middot; <a href=\"/library#work=canons-ecumenical\">पुस्तकालय में पढ़ें</a>",
"k4b650236": "कैनन जिसकी माँग करते हैं वह उपवास है। उसे पिछली आधी रात से गिनना वह रीति है जो उसे वहन करती है, और यह हर क्षेत्राधिकार में साधारण व्यवहार है। जहाँ आराधना संध्या को होती है, जैसे पूर्व-अभिषिक्त उपहारों की, और जैसे जन्मोत्सव, थेओफानिया, पवित्र बृहस्पतिवार और पवित्र शनिवार की आराधनाएँ हो सकती हैं, वहाँ अवधि धर्माध्यक्ष निश्चित करता है, आधी रात से गिनना नहीं। जो औषधि लेनी ही हो, रोग, गर्भावस्था, शैशव और अधिक आयु - इन्हें आध्यात्मिक पिता देखता है। पूछना और छूट पाना एक बात नहीं, और इनमें से कोई भी चालीस से दूर रहने का कारण नहीं।",
"kc182b483": "<strong>चालीस के सामने कही जाने वाली दो प्रार्थनाएँ</strong> - \"हे प्रभु, मैं विश्वास करता हूँ और स्वीकार करता हूँ\" और \"तेरे रहस्यमय भोज की\" - अधिकांश कलीसियाओं में समस्त मंडली के साथ ऊँचे स्वर में कही जाती हैं।",
"kaebd6892": "नियम रूप में मठवासी हैं; जिस जीवन की वे माँग करते हैं वह नहीं",
"keedea2a4": "प्रार्थना-पुस्तक में छपा लगभग हर नियत नियम अपना वर्तमान रूप किसी मठ में पा चुका था, और इसीलिए तैयारी ऐसी पढ़ी जा सकती है मानो किसी और को संबोधित हो। यह आपत्ति इतनी पुरानी है कि संत यूहन्ना क्रिसोस्तोम उत्तर देने से पहले उसे अपने श्रोताओं के मुँह में रख देते हैं:",
"k3f765fe1": "तू कहेगा, मैं मठवासियों में से नहीं, मेरे तो पत्नी और बच्चे हैं और घर की चिंता। यही तो है जिसने सब बिगाड़ दिया, कि तू समझता है कि पवित्र शास्त्रों का पढ़ना केवल उन्हीं का काम है, जबकि तुझे उनसे कहीं अधिक उसकी आवश्यकता है। क्योंकि जो संसार में रहते हैं और प्रतिदिन घाव पाते हैं, उन्हीं को औषधियों की सबसे अधिक आवश्यकता है।",
"kebad4fa3": "संत यूहन्ना क्रिसोस्तोम, मत्ती पर उपदेश 2 &middot; अनु. George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">पुस्तकालय में पढ़ें</a>",
"k5eee983b": "जीवन-शैली के विषय में भी वे यही कहते हैं, और इसे वे जंगल को कानून बनाने से इनकार के रूप में कहते हैं:",
"k00cd498f": "मैं यह कानून नहीं बनाता कि तुम पहाड़ों और जंगलों पर अधिकार करो, बल्कि यह कि तुम भले, विचारशील और पवित्र बनो, नगर के बीच रहते हुए।",
"kc7ddce00": "संत यूहन्ना क्रिसोस्तोम, मत्ती पर उपदेश 7 &middot; अनु. George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">पुस्तकालय में पढ़ें</a>",
"k99a23dda": "और रोमियों पर वे इस विचार को कि साधारण जीवन आज्ञाओं का गलत पता है, विश्वास पर आरोप मानते हैं, उसका वर्णन नहीं:",
"k91017238": "क्योंकि यदि नगरों के बीच रहने वाले के लिए शिष्य होना संभव ही नहीं, तो यह इस जीवन-रीति पर भारी आरोप है, अर्थात् यह कि हमें नगर छोड़कर जंगलों की ओर भागना चाहिए। परंतु मुझे ऐसा मनुष्य दिखा जिसके पत्नी हो, बच्चे हों, परिवार हो, और फिर भी वह ज्ञान की खोज करता हो। तो हम इस सब पर क्या कहें? क्या हमें सिर झुकाकर लज्जित नहीं होना चाहिए? क्योंकि मसीह ने हमें ऐसी आज्ञा नहीं दी; बल्कि कौन सी? कि तुम्हारा प्रकाश मनुष्यों के सामने चमके, न कि पहाड़, जंगल, उजाड़ और एकांत स्थान।",
"kafb2fb07": "संत यूहन्ना क्रिसोस्तोम, रोमियों पर उपदेश 26 &middot; अनु. J. B. Morris और W. H. Simcox &middot; <a href=\"/library#work=chrysostom-homilies-romans\">पुस्तकालय में पढ़ें</a>",
"ke1ee6e3e": "वे तुरंत अगले वाक्य में सावधान रहते हैं कि मठवासियों को नीचा दिखाने वाला न समझा जाए: वे कहते हैं कि वे बोलते हैं \"उनकी निंदा करते हुए नहीं जिन्होंने पहाड़ों को अपनाया, बल्कि उनके लिए विलाप करते हुए जो नगरों में रहते हैं, क्योंकि उन्होंने वहाँ से सद्गुण को निकाल दिया।\" मठवासी अपनी इच्छा किसी बुज़ुर्ग को सौंपता है। गृहस्थ को भी वही सौंपने के लिए दिया गया है - विवाह में, ऐसे काम में जो उसने चुना नहीं, उस धैर्य में जो एक घर माँगता है - और यह उससे ऐसे रूप में माँगा जाता है जिसे कोई नियम पहले से नहीं छाप सकता।",
"ka438020e": "उपवास, स्वीकारोक्ति, और तैयारी का शेष",
"k67ac3841": "तैयारी केवल प्रार्थना नहीं है। बुधवार और शुक्रवार का उपवास उसका सबसे प्राचीन भाग है, और वह दिदाखे के उसी अध्याय में है जो प्रार्थना का नियम देता है:",
"ke069eea2": "परंतु तुम्हारे उपवास कपटियों के साथ न हों; क्योंकि वे सप्ताह के दूसरे और पाँचवें दिन उपवास करते हैं; तुम चौथे दिन और तैयारी के दिन (शुक्रवार) उपवास करो। और कपटियों की भाँति प्रार्थना भी न करो, बल्कि जैसा प्रभु ने अपने सुसमाचार में आज्ञा दी, वैसे प्रार्थना करो: हे हमारे पिता, तू जो स्वर्ग में है...",
"k4e4ee152": "इस अंश की चेतावनी दोनों आधे भागों पर लागू है: उपवास न करने पर नहीं, बल्कि <em>कपटियों की भाँति</em> उपवास करने पर, और प्रार्थना न करने पर नहीं, बल्कि <em>कपटियों की भाँति</em> प्रार्थना करने पर। दिदाखे दोनों नियम एक ही साँस में देता है और दोनों को एक ही रीति से सीमित करता है।",
"k901f0415": "प्रभुभोज से पहले स्वीकारोक्ति कुछ परंपराओं में अपेक्षित है और कुछ में नहीं, और यह अंतर पुराना है, ढील का विषय नहीं। इसे स्पष्ट करना उचित है, क्योंकि जिसने एक परंपरा में तैयारी करना सीखा और फिर दूसरी परंपरा की कलीसिया में पहुँच गया, वह रीति के अंतर को सहज ही अपने ऊपर निर्णय समझ सकता है।",
"k34d94fda": "<strong>स्लाव कलीसियाओं में</strong> - रूसी, विदेश की रूसी, अमेरिका की ऑर्थोडॉक्स कलीसिया, यूक्रेनी, सर्बियाई - सामान्यतः हर प्रभुभोज से पहले स्वीकारोक्ति अपेक्षित है। तैयारी में रीति के अनुसार तीन कानोन आते हैं - उद्धारकर्ता के, परमेश्वर-जननी के, और रक्षक स्वर्गदूत के - और प्रायः परम मधुर प्रभु यीशु का अकाथिस्त भी, तैयारी की प्रार्थनाओं के अतिरिक्त; और पिछली संध्या की रात्रि-जागरण या संध्या-विधि में उपस्थिति तैयारी का भाग मानी जाती है, अलग भक्ति नहीं।",
"k3c46f09c": "<strong>यूनानी, अंताकियाई और रोमानियाई व्यवहार में</strong> स्वीकारोक्ति प्रायः प्रभुभोज से अलग है और आध्यात्मिक पिता द्वारा निश्चित अंतरालों पर होती है, अकसर चार उपवास-कालों में। तैयारी का अर्थ प्रायः तैयारी की प्रार्थनाएँ है, न कि कानोनों और अकाथिस्त का पूरा समूह, और संध्या की विधि का दृढ़ता से प्रोत्साहन है, पर उसे ग्रहण करने की शर्त नहीं बनाया जाता।",
"kbf226744": "दोनों ही समूची स्थानीय कलीसियाओं का स्थापित व्यवहार हैं, और प्रत्येक उस कलीसिया के पुरोहितवर्ग के मार्गदर्शन में निभाया जाता है। यहाँ किसी व्यक्ति का नियम उसके अपने आध्यात्मिक पिता से आता है, न कि उस वर्णन से जो उसने संयोग से पहले पढ़ लिया।",
"k7edee590": "माप पर अंतिम वचन",
"k95bf9581": "नियम इसलिए है कि हम एक ओर आलस्य के वश न हों और दूसरी ओर अपनी सामर्थ्य से आगे स्वयं को न धकेलें। एकांतवासी संत थेओफान सिखाते थे कि मार्ग के दो गड्ढे हैं: दाहिनी ओर बिना ज्ञान का उत्साह; बाईं ओर आलस्य। अति आरंभ करने वाले को असफल होने पर थकावट और निराशा तक पहुँचाती है, और सफल होने पर अभिमान तक। संत इग्नाती ब्रियांचानिनोव ने लिखा कि नियम तेरे लिए है; तू नियम के लिए नहीं है, बल्कि प्रभु के लिए जीता है, और तुझे विवेक की स्वतंत्रता बनाए रखनी है।",
"kd192a6bd": "थोड़े से आरंभ कर। बहुतों को जल्दबाज़ी में पार करने से भला है कि थोड़ी प्रार्थनाएँ ध्यान से कही जाएँ। यदि तेरा आध्यात्मिक पिता है, तो वही नियम निभा जो वह देता है और उसकी आशीष के बिना कुछ न बदल; यदि अभी नहीं है, तो अपनी सामर्थ्य के अनुसार संयत नियम निभा और ऐसा पिता ढूँढ़। कोई पुस्तक और कोई पृष्ठ मसीह में जीवित पिता का स्थान नहीं ले सकता।",
"kb6eb659b": "एकांतवासी संत थेओफान, प्रार्थना-नियम, और संत इग्नाती (ब्रियांचानिनोव) के प्रार्थना-नियम संबंधी लेखों से &middot; <a href=\"/#guide\">मार्गदर्शिका में भी</a>",
"keda0cc2f": "इस स्थल पर कुछ भी ऐसा तराजू नहीं जिस पर किसी को तौला जाए। यह एक पुस्तकालय है और एक पंचांग।",
"kc89cd31d": "प्रार्थना का नियम निश्चित समयों पर रखी गई प्रार्थना की एक निश्चित मात्रा है। यह पृष्ठ बताता है कि मात्रा के विषय में कलीसिया के स्रोत क्या कहते हैं, और नियम प्रायः कौन-से रूप लेता है।",
"k36c2948e": "<strong>पहले यह पढ़ें।</strong> जो नियम आप रखते हैं वह आपके आध्यात्मिक पिता निर्धारित करते हैं, आपकी शक्ति और आपकी परिस्थितियों के अनुसार। यहाँ जो छपा है वह विरासत है, कोई मापदंड नहीं जिससे किसी को तौला जाए। जो प्रभु की प्रार्थना दिन में तीन बार कहता है और सच्चे मन से कहता है, वह उसी नियम को रख रहा है जो कलीसिया ने पहली शताब्दी में दिया था।",
"k530f73b4": "नियम कहाँ से आया",
"kc776efc1": "दो अध्याय पहले वही दस्तावेज़ माप बताता है, और यह इस विषय पर कलीसिया का लिखा सबसे प्राचीन वचन है:",
"k81f4ff1a": "प्रार्थना-पुस्तकों में जो कुछ है वह बाद में आया। और निश्चित घड़ियों का नियम प्रार्थना की सेवा करता है, उसे समाप्त नहीं करता: प्रेरित का <em>निरन्तर प्रार्थना करते रहो</em> (1 थिस्सलुनीकियों 5:17) व्यापक माप है, और सन्त योहान कस्सियन, मिस्र के पिताओं को लिखते हुए, इसे तीखे शब्दों में कहते हैं।",
"k071c623f": "नियम के रूप",
"k28364d47": "ये वे रूप हैं जो एक गृहस्थ का नियम प्रायः लेता है, इस क्रम में रखे गए कि प्रत्येक दिन में से कितना माँगता है। यह चढ़ने की सीढ़ी नहीं है: पहला वही है जिसे हेसिकास्ट पिता सम्पूर्ण प्रार्थना कहते हैं, और जो सबसे आगे बढ़े हुओं को हर लिखी हुई वस्तु के स्थान पर दिया जाता है। <strong>इनमें से कौन-सा आप पर लागू होता है, यह आपके आध्यात्मिक पिता से पूछने की बात है।</strong>",
"kf8b6b4bc": "बिना निश्चित समय की प्रार्थना &middot; जब न समय हो, न पुस्तक, न शान्ति",
"k491be6c4": "<em>हे प्रभु येशु मसीह, परमेश्वर के पुत्र, मुझ पापी पर दया कर।</em> जहाँ यह भी अधिक हो, वहाँ पिता छोटे रूपों की अनुमति देते हैं - <em>हे प्रभु येशु मसीह, मुझ पर दया कर</em>, अथवा केवल <em>हे प्रभु, दया कर</em>। इसे न पुस्तक चाहिए, न खड़ा होना, न स्वर, और इसे काम के पूरे दिन साथ लिया जा सकता है। यह पहले इसलिए आता है कि यह हर परिस्थिति में टिकती है, इसलिए नहीं कि यहाँ जो कुछ है उसमें सबसे छोटी है।",
"k2d14e1b1": "निश्चित समयों पर एक छोटा नियम &middot; दिदाखे",
"k25c1035a": "निश्चित प्रार्थनाएँ, दिन भर चलने वाली प्रार्थना से जुड़ी हुई &middot; उनके लिए जिनका काम अधिक के लिए स्थान नहीं छोड़ता",
"ke0ae2493": "सन्त सेराफ़िम ने इसे उन मज़दूरों और गृहस्थों को दिया जो पूर्ण प्रार्थनाएँ नहीं रख सकते थे, और उन्होंने इसे ऐसी रियायत नहीं माना जिससे बड़े होकर निकल जाना हो।",
"kc0703990": "उठते समय प्रातःकाल की प्रार्थनाएँ और सोने से पहले सन्ध्या की प्रार्थनाएँ, ध्यान से कही गई, जल्दबाज़ी में नहीं। सन्त थेओफ़ान एकान्तवासी इन्हें आरम्भ करने वाले गृहस्थ के लिए पूर्णतः पर्याप्त मानते थे।",
"k030dfcd7": "उपासनाओं का दैनिक चक्र &middot; जहाँ दिन इसकी अनुमति दे",
"k129ba7c3": "दिन भर की छोटी उपासनाएँ, प्रथम घड़ी से लेकर रात्रि-प्रार्थना तक। दिदाखे की तीन दैनिक प्रार्थनाएँ इस चक्र का बीज हैं; पूर्ण घड़ियाँ घड़ी-पुस्तक में दी गई हैं।",
"k6ca85803": "अवसर का नियम &middot; रहस्यों को ग्रहण करने से पहले",
"kc26de5d2": "यात्रा, रोग, रात की नौकरी, छोटे बच्चे, शोक और थकान - ये सब नियम को तोड़ते हैं। ऊपर के दो पाठ इससे सीधे सम्बन्ध रखते हैं। दिदाखे अपने नियम को सब कुछ या कुछ नहीं के रूप में प्रस्तुत नहीं करता: जहाँ पूरा जूआ नहीं उठाया जा सकता, \"जो तू कर सकता है, वही कर\"। और कस्सियन उन्हें डाँटते हैं जो अपनी प्रार्थना केवल घुटने टेकने की घड़ियों से गिनते हैं - जो उन घड़ियों के बाहर की प्रार्थना को गिनती के भीतर लाता है, बाहर नहीं करता।",
"k892d0484": "तैयारी की विधि सचमुच एक भलाई और सचमुच एक विरासत है। किन्तु वही मनुष्य को ग्रहण करने योग्य नहीं बनाती। सन्त योहान क्रिसोस्तोम कितनी बार और कितना, यह प्रश्न उठाते हैं और उन्हीं शब्दों में उत्तर देने से इनकार करते हैं:",
"k74472bee": "जिस कसौटी का वे नाम लेते हैं वह अन्तःकरण की दशा है, कोई संख्या नहीं। सन्त योहान कस्सियन दूसरे आधे को उस अध्याय-शीर्षक के अन्तर्गत लेते हैं जो बात साफ़ कहता है: <em>कि यद्यपि हम मानते हैं कि हम पाप रहित नहीं हो सकते, तथापि हमें प्रभु की समागति से स्वयं को अलग नहीं करना चाहिए।</em>",
"k89f08ec2": "अयोग्यता के भाव से दूर रहना, वे तर्क करते हैं, स्वयं ही बड़ा दुस्साहस है: जो योग्य होने तक दूर रहता है वह मान लेता है कि किसी और दिन वह योग्य होता। रहस्य शुद्धों के लिए पुरस्कार नहीं, वरन् उन्हीं के शब्दों में, ग्रहण करने से ही हमें सन्त और शुद्ध बनाते हैं।",
"ke31bdf96": "यह मापदंड को घटाना नहीं है। यही मापदंड है, और कलीसिया इसे हर निकट आने वाले के मुँह में रखती है:",
"kfbddc832": "प्रेरित के अपने शब्द हैं <em>मसीह येशु पापियों का उद्धार करने जगत में आया, जिनमें मुख्य मैं हूँ</em>, और कलीसिया ने उन्हें पत्री में नहीं छोड़ा: उसने उन्हें उपासना में ले लिया और हर समागति लेने वाले को दिया कि वह उन्हें उत्तम पुरुष में कहे, उसी दिन जब वह ग्रहण करता है। सन्त वे हैं जिन्होंने वह वाक्य कहा और सच्चे मन से कहा, न कि वे जो ऐसे स्थान पर पहुँच गए जहाँ वह लागू होना बन्द हो गया।",
"k7981c058": "<strong>परम्परा जिनका नाम लेती है</strong> वे हैं ऐसा अन्तःकरण जो बिना पश्चात्ताप किए पाप में विश्राम न करे, पड़ोसी से मेल, समागति से पहले का उपवास, और स्वीकारोक्ति के विषय में आध्यात्मिक पिता की आज्ञाकारिता।",
"keeb5d497": "<strong>समागति से पहले का उपवास कैननिक है, प्रथा मात्र नहीं।</strong> 419 की अफ़्रीकी संहिता इसकी माँग करती थी और वर्ष में एक अपवाद देती थी; त्रुल्लो की महासभा ने उस कैनन को लिया और वह अपवाद हटा दिया:",
"k718a2fab": "किन्तु चूँकि कोई बात हमें यथार्थ पालन छोड़ने की ओर नहीं ले जाती, हम ठहराते हैं कि प्रेरितिक और पितृ-परम्परा का अनुसरण किया जाए, और निर्धारित करते हैं कि महाउपवास के अन्तिम सप्ताह के पाँचवें दिन उपवास तोड़ना और इस प्रकार सम्पूर्ण महाउपवास का अनादर करना उचित नहीं है।",
"k2426bb65": "कैनन जिसकी माँग करते हैं वह उपवास है। उसे पिछली आधी रात से गिनना वह प्रथा है जो उसे वहन करती है। जहाँ धर्मविधि सन्ध्या को की जाती है - पूर्व-पवित्रीकृत उपहारों की, तथा जन्मपर्व, थियोफ़नी, महागुरुवार और महाशनिवार की धर्मविधियाँ - वहाँ अवधि बिशप निर्धारित करते हैं, आधी रात से नहीं गिनी जाती। जो औषधि लेनी ही पड़े, रोग, गर्भावस्था, शिशु-अवस्था और अत्यन्त वृद्धावस्था - इन सबका समाधान आध्यात्मिक पिता करते हैं। पूछना छूट पा जाने के समान नहीं है, और इनमें से कोई भी कटोरे से दूर रहने का कारण नहीं है।",
"ka41be440": "वे मरुभूमि को विधान बनाने से इनकार करते हैं - \"मैं तुम्हारे लिए यह विधान नहीं बनाता कि पहाड़ों और मरुभूमियों पर अधिकार करो, वरन् यह कि नगर के बीच रहते हुए भले, विचारशील और पवित्र बनो\" - और वे सावधान हैं कि उन्हें मठवासियों का अनादर करने वाला न समझा जाए, यह कहते हुए कि वे बोलते हैं \"उनको गाली देते हुए नहीं जिन्होंने पहाड़ों को अपनाया, वरन् उन पर विलाप करते हुए जो नगरों में रहते हैं, क्योंकि उन्होंने वहाँ से सद्गुण को निकाल दिया है\"। मठवासी अपनी इच्छा एक वृद्ध को सौंप देता है। गृहस्थ को भी वही सौंपने को दिया गया है - विवाह में, ऐसे काम में जिसे उसने नहीं चुना, उस धैर्य में जो एक घर माँगता है - और यह उससे ऐसे रूप में माँगा जाता है जिसे कोई नियम पहले से छाप नहीं सकता।",
"ke5795f78": "उपवास और स्वीकारोक्ति",
"k6602f295": "तैयारी केवल प्रार्थना नहीं है। बुधवार और शुक्रवार का उपवास उसका सबसे प्राचीन भाग है, और वह दिदाखे के उसी अध्याय में है जो प्रार्थना का नियम देता है - जो दोनों भागों को एक ही प्रकार से सीमित करता है, न उपवास छोड़ने से न प्रार्थना छोड़ने से चेतावनी देते हुए, वरन् इन दोनों में से किसी को <em>कपटियों के समान</em> करने से।",
"k159fbd83": "समागति से पहले स्वीकारोक्ति कुछ परम्पराओं में अपेक्षित है और कुछ में नहीं, और यह भेद पुराना है, ढील का विषय नहीं। जिसने एक परम्परा में तैयारी करना सीखा और फिर दूसरी की कलीसिया में जा पहुँचा, वह प्रथा के भेद को सहज ही अपने ऊपर निर्णय मान सकता है।",
}
